{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "TaClo, a 1-substituted tetrahydro-beta-carboline closely related to the query's beta-carboline core, crossed the BBB in rats and was eliminated from brain about 2.5 times more slowly than from plasma, directly supporting CNS access for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Premazepam, a fused heterocycle with high transferability, readily crossed the blood-brain barrier in monkey whole-body autoradiography with homogeneous brain distribution, supporting CNS penetration of related fused heterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "In humans, [11C]yohimbine, an indole alkaloid, showed brain uptake by PET, demonstrating that indole-alkaloid-type structures can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "MK-7622 entered the CNS in adequate amounts in human Phase 1 CSF pharmacokinetic studies, providing direct human evidence that structurally related fused heterocycles achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A close beta-carboline/tryptamine analogue, 20o.HCl, was labeled as good penetration with an in vivo brain-to-plasma ratio of 0.4 in mice, showing meaningful CNS access for close analogues.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Harmalan and its beta-carboline scaffold are consistently supported by high-transfer experimental evidence: close analogues cross the BBB in rodents, monkeys, and humans, with brain-to-plasma ratios in the permeable/good range and human CSF/PET uptake. Therefore, meaningful CNS access after systemic administration is predicted.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma or CSF measurement for harmalan itself; prediction relies on high-transfer analogues.",
    "Efflux-transporter status (P-gp/BCRP) for harmalan was not directly measured, though the analogue evidence suggests adequate net CNS access.",
    "Most quantitative ratios are from mice; human evidence is qualitative/CSF or PET rather than a formal brain-to-plasma ratio for the exact query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

